-- Baseline pulled from production (hikvjnpkvnxibfzdnpig) with `supabase db pull` on 2026-09-24.
-- Generated by the CLI, then edited in exactly four places, each marked "Baseline edit":
--   1. the song-job-emails webhook trigger is removed (it embeds a secret),
--   2. the storage buckets are appended (db pull captures schema, not bucket rows),
--   3. a Realtime-owned trigger is removed (the Realtime service creates it itself), and
--   4. the trailing table REVOKEs are moved before the GRANTs (else column grants are lost).
-- Production already records this version as applied in supabase_migrations.schema_migrations.




SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA "extensions";






COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";





SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."crm_issues" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "job_id" "uuid",
    "user_id" "uuid",
    "kind" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "detail" "text",
    "resolved_at" timestamp with time zone,
    CONSTRAINT "crm_issues_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'ack'::"text", 'resolved'::"text"])))
);


ALTER TABLE "public"."crm_issues" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."crm_notes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
