    "user_id" "uuid",
    "enquiry_id" "uuid",
    "body" "text" NOT NULL,
    CONSTRAINT "crm_notes_target" CHECK ((("user_id" IS NOT NULL) OR ("enquiry_id" IS NOT NULL)))
);


ALTER TABLE "public"."crm_notes" OWNER TO "postgres";


