    "name" "text" NOT NULL,
    "email" "text" NOT NULL,
    "role" "text" NOT NULL,
    "company" "text",
    "catalogue_size" "text",
    "target_languages" "text"[],
    "message" "text",
    "source" "text",
    "unlocked_audio" boolean DEFAULT false NOT NULL,
    "user_agent" "text",
    "referrer" "text",
    "handled" boolean DEFAULT false NOT NULL,
