-- Baseline edit 3. db pull also emitted CREATE TRIGGER tr_check_filters ON realtime.subscription.
-- That object belongs to the Supabase Realtime service, which creates it itself; it is not ours
-- and fails on a stack without Realtime, so it is dropped here.


  create policy "deliveries_own_select"
  on "storage"."objects"
  as permissive
  for select
  to authenticated
using (((bucket_id = 'deliveries'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));



  create policy "submissions_own_insert"
  on "storage"."objects"
  as permissive
  for insert
  to authenticated
with check (((bucket_id = 'submissions'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));



  create policy "submissions_own_select"
  on "storage"."objects"
  as permissive
  for select
  to authenticated
using (((bucket_id = 'submissions'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));



  create policy "voice_training_own_insert"
  on "storage"."objects"
  as permissive
  for insert
  to authenticated
with check (((bucket_id = 'voice-training'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));



  create policy "voice_training_own_select"
  on "storage"."objects"
  as permissive
  for select
  to authenticated
using (((bucket_id = 'voice-training'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));


